from desk.label_ellipsis import truncate_label
for value in ('', 'a', 'abcd', '😀é中z'):
    for limit in range(6):
        result = truncate_label(value, limit)
        assert len(result) <= limit
        assert result == (value if len(value) <= limit else value[:limit - 1] + '…') if limit else result == ''
for limit in (-1, True, 1.5, '2', None):
    try:
        truncate_label('abcd', limit)
    except ValueError:
        pass
    else:
        raise AssertionError(limit)
print('Boundary, Unicode, and invalid-limit checks passed.')
